public int MaxDepth(TreeNode root) =>
    root == null ? 0 : 1 + Math.Max(MaxDepth(root.left), MaxDepth(root.right));

// the same code, step by step of the template
int Depth(TreeNode node) {
    if (node == null) return 0;          // 1. answer for the empty tree
    int l = Depth(node.left);            // 2. ask the children
    int r = Depth(node.right);
    return 1 + Math.Max(l, r);           // 3. combine into the node's answer
}

