// nearest descendant with a tag: BFS, no recursion, no garbage
readonly Queue<Transform> queue = new Queue<Transform>(64);

Transform FindNearest(Transform root, string tag) {
    queue.Clear();
    queue.Enqueue(root);
    while (queue.Count > 0) {
        var t = queue.Dequeue();
        if (t.CompareTag(tag)) return t;        // CompareTag creates no string
        for (int i = 0; i < t.childCount; i++)
            queue.Enqueue(t.GetChild(i));       // no foreach: no enumerator
    }
    return null;
}
